/* @lc app=leetcode id=3897 lang=kotlin */ class Solution { fun maxValue(nums1: IntArray, nums0: IntArray): Int = 1_000_000_007L.let { M -> generateSequence(1L) { it * 2 % M }.take(20002).toList().let { pw -> nums1.indices.sortedWith(compareBy({ if (nums0[it] == 0) 0 else 1 }, { -nums1[it] }, { nums0[it] })).fold(0L) { v, i -> (v * pw[nums1[i] + nums0[i]] + ((pw[nums1[i]] - 1 + M) % M) * pw[nums0[i]]) % M }.toInt() } } }